function h3RefPrompt(subjectLine, description, soundscape, music) {
  return `subject_definitions:
<Subject 1> ${subjectLine}

integrated_multimodal_description: ${description}

overall_soundscape: ${soundscape}

non_diegetic_music: ${music}`;
}

function P(group, title, tests, wardrobe, description, soundscape, music) {
  return {
    group,
    title,
    tests,
    text: h3RefPrompt(
      `a woman, natural authentic human appearance, expressive eyes, ${wardrobe}`,
      description,
      soundscape,
      music || "N/A",
    ),
  };
}

